CREATE TABLE IF NOT EXISTS tasks (id BIGINT AUTO_INCREMENT PRIMARY KEY,project_id BIGINT NOT NULL,title VARCHAR(200) NOT NULL,description TEXT NOT NULL,status VARCHAR(20) NOT NULL,priority VARCHAR(20) NOT NULL,assigned_user BIGINT NULL,created_by BIGINT NOT NULL,labels TEXT NOT NULL,due_date VARCHAR(10) NULL,created_at VARCHAR(40) NOT NULL,updated_at VARCHAR(40) NOT NULL,version INT NOT NULL DEFAULT 1,INDEX(project_id));
CREATE TABLE IF NOT EXISTS comments (id BIGINT AUTO_INCREMENT PRIMARY KEY,task_id BIGINT NOT NULL,user_id BIGINT NOT NULL,body TEXT NOT NULL,created_at VARCHAR(40) NOT NULL,FOREIGN KEY(task_id) REFERENCES tasks(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS outbox (id BIGINT AUTO_INCREMENT PRIMARY KEY,event_id VARCHAR(64) NOT NULL UNIQUE,user_id BIGINT NOT NULL,title VARCHAR(200) NOT NULL,message VARCHAR(500) NOT NULL,link VARCHAR(200) NOT NULL);
